import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < M) {
        float sum = 0.0f;
        for (int col = 0; col < K; col++) {
            sum += A[row * K + col] * B[col];
        }
        C[row] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int64_t M = A.size(0);
    int64_t K = A.size(1);

    // Flatten B if it has shape (K, 1)
    if (B.dim() == 2 && B.size(1) == 1) {
        B = B.view({B.size(0)});
    }

    auto out = torch::zeros({M}, A.options());

    const int block_size = 256;
    const int grid_size = (M + block_size - 1) / block_size;
    matmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), out.data_ptr<float>(), M, K
    );
    return out.view({M, 1});
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_ext = load_inline(
    name="matmul_ext",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matmul_ext.matmul_cuda(A, B)

M = 256
K = 131072

def get_inputs():
    A = torch.randn(M, K).cuda()
    B = torch.randn(K, 1).cuda()
    return [A, B]

def get_init_inputs():
    return []
